  from (values
    (1188, 'law_management', 'elaw-rc-concept', 'concept', 1, 'Reading Comprehension — परिचय',
     $j${"text":"Reading Comprehension में दिए गए गद्यांश को पढ़कर प्रश्नों के उत्तर देने होते हैं। सफलता के लिए मुख्य विचार (main idea), लेखक का दृष्टिकोण और अनुमान (inference) समझना ज़रूरी है। उत्तर हमेशा गद्यांश में दिए तथ्यों पर आधारित होना चाहिए, बाहरी ज्ञान पर नहीं।","note":"उत्तर गद्यांश से ही लें"}$j$,
