     $j${"questions":[{"q":"सही वाक्य चुनिए:","options":["She go to school.","She goes to school.","She gone to school.","She going to school."],"answer":1,"explanation":"She (एकवचन) के साथ 'goes' आता है।"},{"q":"'___ apple' में सही article क्या है?","options":["a","an","the","कोई नहीं"],"answer":1,"explanation":"'apple' स्वर ध्वनि से शुरू होता है, इसलिए 'an'।"}]}$j$,
     'english-law', array[]::text[], array[]::text[], 'medium'),

