     'english-law', array[]::text[], array[]::text[], 'medium'),

    (1191, 'law_management', 'elaw-para-concept', 'concept', 1, 'Para Jumbles — वाक्य-क्रम',
     $j${"text":"Para Jumbles में बिखरे वाक्यों को सही क्रम में लगाना होता है। पहला वाक्य अक्सर परिचय देता है (सामान्य या विषय का संकेत), और अंतिम वाक्य निष्कर्ष। सर्वनाम (he, it, this) और संयोजक (however, therefore, also) सही क्रम के सुराग देते हैं।","note":"सर्वनाम हमेशा उससे पहले के वाक्य से जुड़ता है"}$j$,
