     'english-law', array[]::text[], array[]::text[], 'medium'),
    (1191, 'law_management', 'elaw-para-example', 'example', 3, 'उदाहरण',
     $j${"question":"वाक्य: (1) इसलिए, वह दिन-रात मेहनत करता है। (2) राहुल का सपना डॉक्टर बनना है। (3) वह एक गरीब परिवार से है। सही क्रम?","solution":"पहले विषय का परिचय (2), फिर उसका संदर्भ (3), फिर 'इसलिए' से जुड़ा परिणाम (1)।","answer":"2-3-1"}$j$,
     'english-law', array[]::text[], array[]::text[], 'medium'),
