     $j${"questions":[{"q":"Para jumble में सबसे पहला वाक्य अक्सर कैसा होता है?","options":["निष्कर्ष","परिचय / सामान्य कथन","उदाहरण","सर्वनाम से शुरू"],"answer":1,"explanation":"पहला वाक्य सामान्यतः परिचय या सामान्य कथन होता है।"},{"q":"'However' जैसा संयोजक किस संकेत का काम करता है?","options":["विरोध या अंतर","समय","स्थान","सूची"],"answer":0,"explanation":"'However' विरोध या अंतर दिखाता है।"}]}$j$,
     'english-law', array[]::text[], array[]::text[], 'medium'),

    (1192, 'law_management', 'qlaw-num-concept', 'concept', 1, 'Number System — संख्या पद्धति',
     $j${"text":"Number System में प्राकृत संख्याएँ (1, 2, 3...), पूर्ण संख्याएँ (0 सहित), पूर्णांक, परिमेय और अपरिमेय संख्याएँ आती हैं। भाज्यता (divisibility) के नियम और HCF/LCM इसके मुख्य विषय हैं।","note":"2 से भाज्यता: अंतिम अंक सम हो"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
