     $j${"formula":"2 → अंतिम अंक सम · 3 → अंकों का योग 3 से भाज्य · 5 → अंतिम अंक 0 या 5 · 9 → अंकों का योग 9 से भाज्य","explanation":"प्रमुख भाज्यता नियम"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
