     'quant-law', array[]::text[], array[]::text[], 'medium'),

    (1193, 'law_management', 'qlaw-pct-concept', 'concept', 1, 'Percentage — प्रतिशत',
     $j${"text":"प्रतिशत का अर्थ है 100 में से कितना भाग। किसी संख्या का x% = (x/100) × संख्या। वृद्धि/कमी में मूल मान से तुलना होती है। दो क्रमिक परिवर्तन हों तो उन्हें गुणा करके एक साथ परिणाम निकाला जा सकता है।","note":"मूल मान हमेशा आधार होता है"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
    (1193, 'law_management', 'qlaw-pct-formula', 'formula', 2, 'प्रतिशत सूत्र',
