     'quant-law', array[]::text[], array[]::text[], 'medium'),
    (1193, 'law_management', 'qlaw-pct-example', 'example', 3, 'उदाहरण',
     $j${"question":"किसी वस्तु का मूल्य ₹200 से बढ़कर ₹250 हो गया। प्रतिशत वृद्धि कितनी?","solution":"वृद्धि = 250 − 200 = 50; प्रतिशत = (50 ÷ 200) × 100 = 25%","answer":"25%"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
    (1193, 'law_management', 'qlaw-pct-mcq', 'mcq', 4, 'अभ्यास प्रश्न',
     $j${"questions":[{"q":"200 का 15% कितना है?","options":["25","30","35","20"],"answer":1,"explanation":"(15/100) × 200 = 30।"},{"q":"कीमत ₹100 से ₹80 हो गई। कितने प्रतिशत की कमी?","options":["10%","20%","25%","30%"],"answer":1,"explanation":"कमी = 20; (20 ÷ 100) × 100 = 20%।"}]}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),

    (1194, 'law_management', 'qlaw-ratio-concept', 'concept', 1, 'Ratio and Proportion — अनुपात और समानुपात',
     $j${"text":"अनुपात दो समान राशियों की तुलना है (a : b)। समानुपात में दो अनुपात बराबर होते हैं (a : b = c : d)। ये अक्सर साझेदारी, मिश्रण और अनुपातिक बँटवारे में आते हैं। कुल भाग = योग भागों का, और हर भाग का मान सूत्र से निकलता है।","note":"a : b = c : d ⇔ ad = bc"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
    (1194, 'law_management', 'qlaw-ratio-formula', 'formula', 2, 'मुख्य सूत्र',
     $j${"formula":"a : b = c : d ⇔ ad = bc · हिस्सा = (अनुपात भाग ÷ कुल भाग) × कुल राशि","explanation":"समानुपात और बँटवारे के सूत्र"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
    (1194, 'law_management', 'qlaw-ratio-example', 'example', 3, 'उदाहरण',
     $j${"question":"₹1200 को 3:5 के अनुपात में दो लोगों में बाँटना है। छोटे हिस्से का मान?","solution":"कुल भाग = 3+5 = 8; छोटा हिस्सा = (3 ÷ 8) × 1200 = ₹450","answer":"₹450"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
    (1194, 'law_management', 'qlaw-ratio-mcq', 'mcq', 4, 'अभ्यास प्रश्न',
     $j${"questions":[{"q":"यदि 2 : 3 = 4 : x हो, तो x का मान?","options":["5","6","8","9"],"answer":1,"explanation":"2x = 12, इसलिए x = 6।"},{"q":"₹600 को 1:2 में बाँटें तो बड़ा हिस्सा?","options":["₹200","₹300","₹400","₹500"],"answer":2,"explanation":"कुल भाग 3; बड़ा हिस्सा = (2/3) × 600 = ₹400।"}]}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),

    (1195, 'law_management', 'qlaw-di-concept', 'concept', 1, 'Data Interpretation — आँकड़ों का विश्लेषण',
     $j${"text":"Data Interpretation में दिए गए चार्ट, तालिका या ग्राफ़ से प्रश्नों के उत्तर निकाले जाते हैं। सबसे पहले शीर्षक, इकाई (unit) और कुल योग समझें। फिर प्रश्न के हिसाब से आवश्यक आँकड़े चुनें। औसत, प्रतिशत और अनुपात अक्सर पूछे जाते हैं।","note":"पहले इकाई (₹, हज़ार, %) जाँचें"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
