     $j${"formula":"औसत = कुल योग ÷ संख्या-गणना · प्रतिशत हिस्सा = (भाग ÷ कुल) × 100 · वृद्धि % = (नया − पुराना) ÷ पुराना × 100","explanation":"DI में सबसे अधिक उपयोग होने वाले सूत्र"}$j$,
     'quant-law', array[]::text[], array[]::text[], 'medium'),
    (1195, 'law_management', 'qlaw-di-example', 'example', 3, 'उदाहरण',
